class Solution {
public:
    std::vector<std::vector<int>> spiralMatrix(int m, int n, ListNode* head) {
        std::vector<std::vector<int>> res(m, std::vector<int>(n, -1));
        int top = 0, bottom = m - 1, left = 0, right = n - 1;
        ListNode* cur = head;
        while (cur && top <= bottom && left <= right) {
            for (int c = left; c <= right && cur; ++c) {
                res[top][c] = cur->val;
                cur = cur->next;
            }
            top++;
            for (int r = top; r <= bottom && cur; ++r) {
                res[r][right] = cur->val;
                cur = cur->next;
            }
            right--;
            for (int c = right; c >= left && cur && top <= bottom; --c) {
                res[bottom][c] = cur->val;
                cur = cur->next;
            }
            bottom--;
            for (int r = bottom; r >= top && cur && left <= right; --r) {
                res[r][left] = cur->val;
                cur = cur->next;
            }
            left++;
        }
        return res;
    }
};

class Solution {
    public int[][] spiralMatrix(int m, int n, ListNode head) {
        int[][] res = new int[m][n];
        for (int i = 0; i < m; ++i) {
            java.util.Arrays.fill(res[i], -1);
        }
        int top = 0, bottom = m - 1, left = 0, right = n - 1;
        ListNode cur = head;
        while (cur != null && top <= bottom && left <= right) {
            for (int c = left; c <= right && cur != null; ++c) {
                res[top][c] = cur.val;
                cur = cur.next;
            }
            top++;
            for (int r = top; r <= bottom && cur != null; ++r) {
                res[r][right] = cur.val;
                cur = cur.next;
            }
            right--;
            for (int c = right; c >= left && cur != null && top <= bottom; --c) {
                res[bottom][c] = cur.val;
                cur = cur.next;
            }
            bottom--;
            for (int r = bottom; r >= top && cur != null && left <= right; --r) {
                res[r][left] = cur.val;
                cur = cur.next;
            }
            left++;
        }
        return res;
    }
}

